mapper.select:
SELECT 
  FROM sys09_code A
 WHERE A.sys09_code_id = #{codeId}

mapper.update:
UPDATE sys09_code
   SET sys09_code       = #{code},
       sys09_name       = #{name},
       sys09_seq        = #{seq},
       sys09_note       = #{note},
       sys09_apply_date = #{applyDate},
       sys09_close_yn   = #{closeYn},
       sys09_close_date = #{closeDate}
 WHERE sys09_code_id    = #{codeId}
   AND sys09_company_id = #{companyId}

mapper.delete:
DELETE FROM sys09_code
 WHERE sys09_company_id = #{companyId}
   AND sys09_code_id IN
#{id}

mapper.insert:
INSERT
  INTO sys09_code (sys09_code_id, sys09_code, sys09_name, sys09_seq, sys09_note, sys09_apply_date, sys09_close_yn, sys09_code_kind_id, sys09_company_id, sys09_close_date, sys09_desc)
SELECT f_create_seq(), sys09_code, sys09_name, sys09_seq, sys09_note, sys09_apply_date, sys09_close_yn, sys09_code_kind_id, #{newCompanyId}, sys09_close_date, sys09_desc
  FROM sys09_code
 WHERE sys09_company_id = #{sourceCompanyId}
   AND sys09_code_kind_id = #{codeKindId}
